/**
 * GLB 容器头的校验规则，Runtime 与 runtime-mock 共用（纯计算，不碰文件系统；
 * 读文件的那一层在 `@sparc3d/contracts/node` 的 `validateGlbFile`）。
 */

/** GLB 12 字节头：magic `glTF` + version + 整体长度。 */
export const GLB_HEADER_BYTES = 12;
const GLB_MAGIC = 0x46546c67; // 'glTF'（小端）
const GLB_VERSION = 2;

/**
 * 校验 GLB 头。`header` 至少要有 12 字节，`totalBytes` 是整个文件/缓冲区的长度
 * （头里声明的长度必须与之相等，所以只读了头的调用方要把 stat 出来的大小传进来）。
 */
export function assertGlbHeader(header: Uint8Array, totalBytes: number, source: string): void {
  if (totalBytes < GLB_HEADER_BYTES || header.byteLength < GLB_HEADER_BYTES) {
    throw new Error(`not a GLB file: ${source}`);
  }
  const view = new DataView(header.buffer, header.byteOffset, header.byteLength);
  if (view.getUint32(0, true) !== GLB_MAGIC || view.getUint32(4, true) !== GLB_VERSION || view.getUint32(8, true) !== totalBytes) {
    throw new Error(`invalid GLB header: ${source}`);
  }
}

/** 整个 GLB 都在内存里时的便捷形式。 */
export function assertGlbBytes(bytes: Uint8Array, source: string): void {
  assertGlbHeader(bytes, bytes.byteLength, source);
}
